import pytest
from candidate import longest

@pytest.mark.parametrize("input_list, expected", [
    ([], None),
    (['a'], 'a'),
    (['bb', 'aa'], 'bb'),
    (['ccc', 'dd', 'cc'], 'ccc'),
    (['a', 'bb', 'cc', 'dd'], 'cc'),
    (['a', 'bb'], 'bb'),
    (['aa', 'a', 'aa'], 'aa'),
])
def test_longest_basic_cases(input_list, expected):
    assert longest(input_list) == expected

@pytest.mark.parametrize("input_list, expected", [
    (['', 'a', ''], None),
    (['', ''], None),
    (['a', 'b', 'c', 'a'], 'a'),
    (['a'*10, 'a'*9, 'a'*11], 'a'*11),
    (['a', 'b'*5], 'b'*5),
])
def test_longest_edge_cases(input_list, expected):
    assert longest(input_list) == expected

@pytest.mark.parametrize("input_list, expected", [
    (['a', 'b', 'c'], None),
    (['', 'a', ''], 'a'),
    (['a', 'b', 'c'], None),
    (['a', 'b', 'c'], None),
])
def test_longest_empty_and_none_cases(input_list, expected):
    assert longest(input_list) == expected

@pytest.mark.parametrize("input_list, expected", [
    (['a', 1, 'b'], None),
    (['a', None, 'b'], None),
    (['a', 'b', None], None),
    (['a', 'b', 'c'], None),
])
def test_longest_invalid_types(input_list, expected):
    assert longest(input_list) == expected
